#=

    Module comprising of the discretized time evolution equations for the perfect fluid and BDNK systems in the Cowling approximation. These equations are integrated in time using
    an RK4 scheme. This numerical scheme is second-second order accurate since we use second-order finite differences for spatial derivatives.

=#

module CowlingTDEqs

module RK4
module PerfectFluid

dv1_dt(i::Int64, u1::Vector{Float64}, m::Float64, p::Float64, ε::Float64, ν::Float64, cs::Float64, cs_prime::Float64, r::Float64, h::Float64)::Float64 = (exp(ν)*((r^2*(-2*h*π*r^2*p*(r*(-u1[i-1] + u1[i+1]) + 2*u1[i]*(h + 8*h*π*r^2*ε)) + r*cs*(-(u1[i-1]*((h - r + 2*h*π*r^2*ε)*cs + h*r*cs_prime)) + u1[i+1]*((h + r + 2*h*π*r^2*ε)*cs + h*r*cs_prime)) + 2*u1[i]*(16*h^2*π^2*r^4*ε^2*cs^2 + cs*(-((h^2 + r^2)*cs) + 2*h^2*r*cs_prime) + 2*h^2*π*r^2*ε*(-1 + 2*r*cs*cs_prime))))/h^2 + 2*m^2*(u1[i]*(-1 - 5*cs*(cs - 2*r*cs_prime)) + (r*(4*r*(-2*u1[i] + u1[i-1] + u1[i+1])*cs^2 + h*(-u1[i-1] + u1[i+1])*(1 + 5*cs^2 + 4*r*cs*cs_prime)))/(2.0*h^2)) - r*m*(2*u1[i]*(-1 - 8*π*r^2*p + (-5 + 8*π*r^2*ε)*cs^2 + r*(9 + 8*π*r^2*ε)*cs*cs_prime) + (r*(8*r*(-2*u1[i] + u1[i-1] + u1[i+1])*cs^2 + h*(-u1[i-1] + u1[i+1])*(1 - 8*π*r^2*p + (9 + 8*π*r^2*ε)*cs^2 + 8*r*cs*cs_prime)))/(2.0*h^2))))/(r^3*(r - 2*m))

end

module BDNK

dv1_dt(i::Int64, u1::Vector{Float64}, u2::Vector{Float64}, w1::Vector{Float64}, w2::Vector{Float64}, v1::Vector{Float64}, v2::Vector{Float64}, m::Float64, p::Float64, ε::Float64, ν::Float64, cs::Float64, cs_prime::Float64, cs_prime_prime::Float64, r::Float64, η::Float64, ζ::Float64, τε::Float64, τP::Float64, τQ::Float64, L::Float64, h::Float64)::Float64 = (-3*exp(ν/2.)*v1[i])/(L*(3*ζ + 4*η)*τQ) - (3*exp((3*ν)/2.)*(r - 2*m)*w2[i]*cs^2)/(L*r*(3*ζ + 4*η)*τQ*(p + ε)) - (3*exp(ν)*(r - 2*m)*(-v2[i-1] + v2[i+1])*((L*(3*ζ + 4*η)*τP*cs^2)/3. + (L*(3*ζ + 4*η)*τQ*cs^2)/3.))/(2.0*h*L*r*(3*ζ + 4*η)*τQ*(p + ε)) + (exp(ν)*(r - 2*m)*(-w1[i-1] + w1[i+1])*(3*L*ζ*(p + ε)*cs^2 + 4*L*η*(p + ε)*cs^2 - L*(3*ζ + 4*η)*τP*(p + ε)*cs^2))/(2.0*h*L*r*(3*ζ + 4*η)*τQ*(p + ε)) + (3*exp((3*ν)/2.)*(r - 2*m)*u2[i]*(1 - r/(r - 2*m) - (-1 + r/(r - 2*m))*cs^2 - (8*π*r^3*p*(1 + cs^2))/(r - 2*m) - 4*r*cs*cs_prime))/(2.0*L*r^2*(3*ζ + 4*η)*τQ*(p + ε)) + (3*exp(ν)*(r - 2*m)*v2[i]*(-0.3333333333333333*(L*(3*ζ + 4*η)*(-1 + r/(r - 2*m) + (8*π*r^3*p)/(r - 2*m))*τε) - (4*L*r*(3*ζ + 4*η)*τP*cs*cs_prime)/3. - (L*(3*ζ + 4*η)*τQ*(-1 + r/(r - 2*m) + (-1 + r/(r - 2*m))*cs^2 + (8*π*r^3*p*(1 + cs^2))/(r - 2*m) + 4*r*cs*cs_prime))/3.))/(2.0*L*r^2*(3*ζ + 4*η)*τQ*(p + ε)) + (exp(ν)*(r - 2*m)*w1[i]*((-8*L*π*r^3*(3*ζ + 4*η)*τP*ε^2*cs^4)/(r - 2*m) + (24*π*r^3*p^2*(-0.3333333333333333*(L*(3*ζ + 4*η)*τε*cs^2) + (L*(3*ζ + 4*η)*τP*cs^2*(2 + cs^2))/3.))/(r - 2*m) + ε*(2*L*(3*ζ + 4*η)*τP*cs^2*(-1 + r/(r - 2*m) + (-3 + r/(r - 2*m))*cs^2) + cs^2*(L*(3*ζ + 4*η)*τε - (L*r*(3*ζ + 4*η)*τε)/(r - 2*m) + (24*L*π*r^3*ζ*(p + ε)*cs^2)/(r - 2*m) + (32*L*π*r^3*η*(p + ε)*cs^2)/(r - 2*m) - 4*L*r*(3*ζ + 4*η)*τP*cs*cs_prime)) + 3*p*((2*L*(3*ζ + 4*η)*τP*cs^2*(-1 + r/(r - 2*m) + (8*π*r^3*ε)/(r - 2*m) + (-3 + r/(r - 2*m))*cs^2))/3. - cs^2*((L*(3*ζ + 4*η)*τε*(-1 + r/(r - 2*m) + (8*π*r^3*ε)/(r - 2*m)))/3. + (4*L*r*(3*ζ + 4*η)*τP*cs*cs_prime)/3.)) - cs^2*(3*L*(-5 + r/(r - 2*m))*ζ*(p + ε)*cs^2 + 4*L*(-5 + r/(r - 2*m))*η*(p + ε)*cs^2 - 2*r*((3*L*ζ*(p + ε)*(1 + cs^2 - (r*(1 + 8*π*r^2*p)*(1 + cs^2))/(r - 2*m) + 4*r*cs*cs_prime))/(2.0*r) + (2*L*η*(p + ε)*(1 + cs^2 - (r*(1 + 8*π*r^2*p)*(1 + cs^2))/(r - 2*m) + 4*r*cs*cs_prime))/r))))/(2.0*L*r^2*(3*ζ + 4*η)*τQ*(p + ε)*cs^2) + (exp(ν)*(r - 2*m)*u1[i]*((-128*L*π^2*r^6*(3*ζ + 4*η)*τP*ε^3*cs^6)/(r - 2*m)^2 - (192*π^2*r^6*p^3*(-0.3333333333333333*(L*(3*ζ + 4*η)*τε*cs^2) + (L*(3*ζ + 4*η)*τP*cs^2*(1 + cs^2))/3.))/(r - 2*m)^2 + 2*cs^4*(3*L*(-5 + r^2/(r - 2*m)^2)*ζ*(p + ε)*cs^2 + 4*L*(-2 + r^2/(r - 2*m)^2 - (3*r)/(r - 2*m))*η*(p + ε)*cs^2 - (3*L*(-5 + r/(r - 2*m))*ζ*(p + ε)*(1 + cs^2 - (r*(1 + 8*π*r^2*p)*(1 + cs^2))/(r - 2*m) + 4*r*cs*cs_prime))/2. - 2*L*(1 + r/(r - 2*m))*η*(p + ε)*(1 + cs^2 - (r*(1 + 8*π*r^2*p)*(1 + cs^2))/(r - 2*m) + 4*r*cs*cs_prime)) + (8*π*r^3*ε^2*cs^2*(L*(3*ζ + 4*η)*τP*cs^2*(-1 + (3*r)/(r - 2*m) + 5*(-1 + r/(r - 2*m))*cs^2) + cs^2*(L*(3*ζ + 4*η)*τε - (L*r*(3*ζ + 4*η)*τε)/(r - 2*m) + (48*L*π*r^3*ζ*(p + ε)*cs^2)/(r - 2*m) + (64*L*π*r^3*η*(p + ε)*cs^2)/(r - 2*m) - 4*L*r*(3*ζ + 4*η)*τP*cs*cs_prime)))/(r - 2*m) - p*(cs^2*((24*L*π*r^3*ζ*(p + ε)*(-1 + r/(r - 2*m) + (8*π*r^3*ε)/(r - 2*m))*cs^2)/(r - 2*m) + (32*L*π*r^3*η*(p + ε)*(-1 + r/(r - 2*m) + (8*π*r^3*ε)/(r - 2*m))*cs^2)/(r - 2*m) + L*(3*ζ + 4*η)*τε*((64*π^2*r^6*ε^2*cs^2)/(r - 2*m)^2 - (16*π*r^3*ε*(-1 + r/(r - 2*m) - 2*cs^2))/(r - 2*m) - (-1 + r/(r - 2*m))*(-1 + r/(r - 2*m) + (-5 + r/(r - 2*m))*cs^2)) + 4*L*r*(3*ζ + 4*η)*τP*cs*(1 - r/(r - 2*m) - (-5 + r/(r - 2*m))*cs^2 + (8*π*r^3*ε*(-1 + cs^2))/(r - 2*m))*cs_prime) + L*(3*ζ + 4*η)*τP*cs^2*((-1 + r/(r - 2*m))^2 + 4*(-1 + r/(r - 2*m))^2*cs^2 + (-5 + (3*r^2)/(r - 2*m)^2 - (6*r)/(r - 2*m))*cs^4 + (64*π^2*r^6*ε^2*cs^2*(-3 + cs^2))/(r - 2*m)^2 + 4*r*(-1 + r/(r - 2*m))*cs*cs_prime - (16*π*r^3*ε*(1 - r/(r - 2*m) - (-5 + r/(r - 2*m))*cs^2 + (2*r*cs^4)/(r - 2*m) - 2*r*cs*cs_prime))/(r - 2*m))) + ε*(-(L*(3*ζ + 4*η)*τP*cs^2*((-1 + r/(r - 2*m))^2 + 4*(-1 + r/(r - 2*m))^2*cs^2 + (-5 + (3*r^2)/(r - 2*m)^2 - (6*r)/(r - 2*m))*cs^4 + 4*r*(-1 + r/(r - 2*m))*cs*cs_prime)) + cs^2*(L*(3*ζ + 4*η)*τε + (L*r^2*(3*ζ + 4*η)*τε)/(r - 2*m)^2 - (2*L*r*(3*ζ + 4*η)*τε)/(r - 2*m) + 5*L*(3*ζ + 4*η)*τε*cs^2 + (L*r^2*(3*ζ + 4*η)*τε*cs^2)/(r - 2*m)^2 - (6*L*r*(3*ζ + 4*η)*τε*cs^2)/(r - 2*m) - (24*L*π*r^3*(-1 + r/(r - 2*m))*ζ*(p + ε)*cs^2*(1 + 4*cs^2))/(r - 2*m) - (32*L*π*r^3*η*(p + ε)*cs^2*(-1 + r/(r - 2*m) + 2*(-5 + (2*r)/(r - 2*m))*cs^2))/(r - 2*m) - 4*L*r*(3*ζ + 4*η)*τP*cs*cs_prime + (4*L*r^2*(3*ζ + 4*η)*τP*cs*cs_prime)/(r - 2*m) - 20*L*r*(3*ζ + 4*η)*τP*cs^3*cs_prime + (4*L*r^2*(3*ζ + 4*η)*τP*cs^3*cs_prime)/(r - 2*m) + (24*L*π*r^3*ζ*(p + ε)*cs^2*(1 + cs^2 - (r*(1 + 8*π*r^2*p)*(1 + cs^2))/(r - 2*m) + 4*r*cs*cs_prime))/(r - 2*m) + (32*L*π*r^3*η*(p + ε)*cs^2*(1 + cs^2 - (r*(1 + 8*π*r^2*p)*(1 + cs^2))/(r - 2*m) + 4*r*cs*cs_prime))/(r - 2*m))) + (8*π*r^3*p^2*(L*(3*ζ + 4*η)*τP*cs^2*(2 - (2*r)/(r - 2*m) + (11 - (5*r)/(r - 2*m))*cs^2 - (-5 + r/(r - 2*m))*cs^4 + (8*π*r^3*ε*(-1 + 2*cs^2 + cs^4))/(r - 2*m) - 4*r*cs*cs_prime) - cs^2*((24*L*π*r^3*ζ*(p + ε)*cs^2)/(r - 2*m) + (32*L*π*r^3*η*(p + ε)*cs^2)/(r - 2*m) + 3*((2*L*(3*ζ + 4*η)*τε)/3. - (2*L*r*(3*ζ + 4*η)*τε)/(3.0*(r - 2*m)) - (8*L*π*r^3*(3*ζ + 4*η)*τε*ε)/(3.0*(r - 2*m)) + (5*L*(3*ζ + 4*η)*τε*cs^2)/3. - (L*r*(3*ζ + 4*η)*τε*cs^2)/(3.0*(r - 2*m)) + (8*L*π*r^3*(3*ζ + 4*η)*τε*ε*cs^2)/(3.0*(r - 2*m)) - (4*L*r*(3*ζ + 4*η)*τP*cs*cs_prime)/3.))))/(r - 2*m)))/(4.0*L*r^3*(3*ζ + 4*η)*τQ*(p + ε)*cs^4)

dv2_dt(i::Int64, u1::Vector{Float64}, u2::Vector{Float64}, w1::Vector{Float64}, w2::Vector{Float64}, v1::Vector{Float64}, v2::Vector{Float64}, m::Float64, p::Float64, ε::Float64, ν::Float64, cs::Float64, cs_prime::Float64, cs_prime_prime::Float64, r::Float64, η::Float64, ζ::Float64, τε::Float64, τP::Float64, τQ::Float64, L::Float64, h::Float64)::Float64 = (-3*exp(ν/2.)*v2[i])/(L*(3*ζ + 4*η)*τε) - (3*((L*(3*ζ + 4*η)*τQ)/3. + (L*(3*ζ + 4*η)*τε)/3.)*(-v1[i-1] + v1[i+1])*(p + ε))/(2.0*h*L*(3*ζ + 4*η)*τε) - (3*exp(ν/2.)*w1[i]*(p + ε))/(L*(3*ζ + 4*η)*τε) - (exp(ν)*(r - 2*m)*τQ*(-w2[i-1] + w2[i+1])*cs^2)/(2.0*h*r*τε) + (3*exp(ν/2.)*u1[i]*(p + ε)*(-1 + r/(r - 2*m) + (8*π*r^3*p)/(r - 2*m) + (-5 + r/(r - 2*m) - (8*π*r^3*ε)/(r - 2*m))*cs^2))/(2.0*L*r*(3*ζ + 4*η)*τε*cs^2) + (3*v1[i]*(p + ε)*((L*(3*ζ + 4*η)*τε*(-1 + r/(r - 2*m) + (8*π*r^3*p)/(r - 2*m) + (-5 + r/(r - 2*m) - (8*π*r^3*ε)/(r - 2*m))*cs^2))/3. + (L*(3*ζ + 4*η)*τQ*(-1 + r/(r - 2*m) + (-6 + (2*r)/(r - 2*m) - (8*π*r^3*ε)/(r - 2*m))*cs^2 + (8*π*r^3*p*(1 + cs^2))/(r - 2*m)))/3.))/(2.0*L*r*(3*ζ + 4*η)*τε*cs^2) - (exp(ν)*(r - 2*m)*τQ*w2[i]*(-1 + r/(r - 2*m) - (4*r*(-1 + 2*π*r^2*ε)*cs^2)/(r - 2*m) + (8*π*r^3*p*(1 + 3*cs^2))/(r - 2*m) + 8*r*cs*cs_prime))/(2.0*r^2*τε) - (exp(ν)*(r - 2*m)*τQ*u2[i]*(1 + r^2/(r - 2*m)^2 - (2*r)/(r - 2*m) + cs^2 + (r^2*cs^2)/(r - 2*m)^2 - (2*r*cs^2)/(r - 2*m) + (64*π^2*r^6*p^2*(1 + cs^2))/(r - 2*m)^2 + (16*r^2*cs*cs_prime)/(r - 2*m) + 8*r^2*cs_prime^2 - (16*π*r^3*ε*(-1 - cs^2 + 2*r*cs*cs_prime))/(r - 2*m) + (16*π*r^3*p*(2 + r/(r - 2*m) + (2 + r/(r - 2*m))*cs^2 + 6*r*cs*cs_prime))/(r - 2*m) + 8*r^2*cs*cs_prime_prime))/(4.0*r^3*τε)

end
end

module RK4Surface
module PerfectFluid

dv1_dt(i::Int64, u1::Vector{Float64}, m::Float64, p::Float64, ε::Float64, ν::Float64, cs::Float64, cs_prime::Float64, r::Float64, h::Float64)::Float64 = (exp(ν)*(-4*h*π*r^4*p*(r*(u1[i-2] - 4*u1[i-1]) + u1[i]*(2*h + 3*r + 16*h*π*r^2*ε)) + r^3*cs*((2*r*(2*u1[i] - u1[i-3] + 4*u1[i-2] - 5*u1[i-1]) + h*(3*u1[i] + u1[i-2] - 4*u1[i-1])*(2 + 4*π*r^2*ε))*cs + 2*h*r*(3*u1[i] + u1[i-2] - 4*u1[i-1])*cs_prime) + 4*h^2*r*m*u1[i]*(1 + 8*π*r^2*p + (5 - 8*π*r^2*ε)*cs^2 - r*(9 + 8*π*r^2*ε)*cs*cs_prime) - 4*h^2*m^2*u1[i]*(1 + 5*cs*(cs - 2*r*cs_prime)) + 2*r*m^2*(4*r*(2*u1[i] - u1[i-3] + 4*u1[i-2] - 5*u1[i-1])*cs^2 + h*(3*u1[i] + u1[i-2] - 4*u1[i-1])*(1 + 5*cs^2 + 4*r*cs*cs_prime)) - r^2*m*(8*r*(2*u1[i] - u1[i-3] + 4*u1[i-2] - 5*u1[i-1])*cs^2 + h*(3*u1[i] + u1[i-2] - 4*u1[i-1])*(1 - 8*π*r^2*p + (9 + 8*π*r^2*ε)*cs^2 + 8*r*cs*cs_prime)) + 2*h^2*r^2*u1[i]*(-2*cs^2 + 4*r*(π*r*ε*(-1 + 8*π*r^2*ε*cs^2) + (1 + 2*π*r^2*ε)*cs*cs_prime))))/(2.0*h^2*r^3*(r - 2*m))

end

