module CenterEqs

module BDNK
# O(h^2) forward differences
FD_1_deriv(f::Vector{Float64}, h::Float64)::Float64 = (-3f[1]+4f[2]-f[3])/(2h)
FD_2_deriv(f::Vector{Float64}, h::Float64)::Float64 = (2f[1]-5f[2]+4f[3]-f[4])/h^2
FD_3_deriv(f::Vector{Float64}, h::Float64)::Float64 = (-5f[1]+18f[2]-24f[3]+14f[4]-3f[5])/(2h^3)


function compute_all(λ::Vector{Float64}, cs::Vector{Float64}, p::Float64, ε::Float64, ν::Float64, u1::Vector{Float64}, u2::Vector{Float64}, w1::Vector{Float64}, w2::Vector{Float64}, v1::Vector{Float64}, v2::Vector{Float64}, η::Float64, ζ::Float64, τε::Float64, τP::Float64, τQ::Float64, L::Float64, h::Float64)
    λ_prime_prime = FD_2_deriv(λ, h)
    cs_prime_prime = FD_2_deriv(cs, h)

    u2_0 = u2[1];
    w1_0 = w1[1];
    w2_1 = FD_1_deriv(w2, h);
    v1_1 = FD_1_deriv(v1, h);
    v2_0 = v2[1];
    # equations at center of star
    du1_dt = dt_u1_0()
    du2_dt = dt_u2_0(v2_0)
    dw1_dt = dt_w1_0(v1_1)
    dw2_dt = dt_w2_0()
    dv1_dt = dt_v1_0()
    dv2_dt = dt_v2_0(p, ε, ν, cs[1], cs_prime_prime, u2_0, w1_0, w2_1, v1_1, v2_0, η, ζ, τε, τP, τQ, L)

    return du1_dt, du2_dt, dw1_dt, dw2_dt, dv1_dt, dv2_dt
end

dt_u1_0()::Float64 = 0

dt_u2_0(v2_0::Float64)::Float64 = v2_0

dt_w1_0(v1_1::Float64)::Float64 = v1_1

dt_w2_0()::Float64 = 0

dt_v1_0()::Float64 = 0

dt_v2_0(p::Float64, ε::Float64, ν::Float64, cs::Float64, cs_prime_prime::Float64, u2_0::Float64, w1_0::Float64, w2_1::Float64, v1_1::Float64, v2_0::Float64, η::Float64, ζ::Float64, τε::Float64, τP::Float64, τQ::Float64, L::Float64)::Float64 = -((3*(τQ + τε)*(p + ε)*v1_1 + (3*exp(ν/2.)*(v2_0 + 3*(p + ε)*w1_0))/(L*(3*ζ + 4*η)) + exp(ν)*τQ*(3*cs^2*w2_1 + 2*u2_0*(2*π*(3*p + ε)*(1 + cs^2) + 3*cs*cs_prime_prime)))/τε)
end
end

